'use strict';

const $ = (q, root = document) => root.querySelector(q);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  host:'M4 3h16v7H4z M4 14h16v7H4z M7 6.5h.01 M7 17.5h.01 M11 6.5h6 M11 17.5h6',
  backup:'M12 3v12 M8 7l4-4 4 4 M5 12H3v8h18v-8h-2 M7 17h10',
  history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2',
  plus:'M12 5v14 M5 12h14', search:'M10.5 3a7.5 7.5 0 1 0 0 15a7.5 7.5 0 0 0 0-15 M16 16l5 5',
  arrow:'M5 12h14 M14 7l5 5-5 5', check:'M5 12l4 4L19 6',
  restart:'M20 8a8 8 0 1 0 0 8 M20 3v5h-5', stop:'M6 6h12v12H6z',
  play:'M7 4l14 8-14 8z', terminal:'M4 7l5 5-5 5 M12 17h8',
  update:'M12 20V4 M5 11l7-7 7 7', close:'M6 6l12 12 M18 6L6 18',
  clock:'M12 3a9 9 0 1 0 0 18a9 9 0 0 0 0-18 M12 7v5l3 2',
  cloud:'M6 18a5 5 0 0 1-1-10a7 7 0 0 1 13 1a4.5 4.5 0 0 1 0 9z',
  shield:'M12 3l8 3v6c0 4-4 7-8 9c-4-2-8-5-8-9V6z M8 12l3 3 5-6',
  more:'M5 12h.01 M12 12h.01 M19 12h.01', info:'M12 8h.01 M12 11v6 M12 3a9 9 0 1 0 0 18a9 9 0 0 0 0-18'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.grid}"/></svg>`;
const uid = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
const stamp = () => new Date().toLocaleTimeString('zh-TW', {hour12:false});
const formatDate = n => new Date(n).toLocaleString('zh-TW', {month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const navs = [{id:'services',label:'服務總覽',icon:'grid'}, {id:'hosts',label:'主機',icon:'host'}, {id:'backups',label:'備份與還原',icon:'backup'}, {id:'history',label:'執行紀錄',icon:'history'}];
const actionNames = {upgrade:'更新',start:'啟動',stop:'停止',restart:'重新啟動',backup:'備份',restore:'還原'};
const mockNow = Date.now();
const seed = {
  hosts:[{id:'h1',name:'nas-host',address:'192.0.2.10',platform:'OpenMediaVault',online:true,central:true},{id:'h2',name:'compute-host',address:'192.0.2.20',platform:'Ubuntu 24.04',online:true},{id:'h3',name:'remote-host',address:'192.0.2.30',platform:'Debian 12',online:true}],
  services:[
    {id:'s1',name:'Magpie',host:'h1',kind:'Docker Compose',version:'0.9.2',latest:'0.9.3',status:'online',logo:'M',color:''},
    {id:'s2',name:'ServerBox WebDAV',host:'h1',kind:'Docker Compose',version:'2.5.1',latest:'2.5.1',status:'online',logo:'S',color:'blue'},
    {id:'s3',name:'Immich',host:'h1',kind:'Docker Compose',version:'1.118.0',latest:'1.119.0',status:'online',logo:'I',color:'rose'},
    {id:'s4',name:'AdGuard Home',host:'h2',kind:'Docker Compose',version:'0.107.53',latest:'0.107.53',status:'online',logo:'A',color:''},
    {id:'s5',name:'Uptime Kuma',host:'h2',kind:'Docker Compose',version:'1.23.15',latest:'1.23.15',status:'online',logo:'U',color:'purple'},
    {id:'s6',name:'Nginx Proxy Manager',host:'h3',kind:'Docker Compose',version:'2.12.1',latest:'2.12.1',status:'stopped',logo:'N',color:'blue'}
  ],
  backups:[{id:'b1',client:'Magpie',name:'magpie-20261027-0830.zip',date:mockNow-3600000,size:'12.4 MB'}, {id:'b2',client:'Flutter ServerBox',name:'serverbox-20261027-0830.zip',date:mockNow-3600000,size:'2.8 MB'}, {id:'b3',client:'Magpie',name:'magpie-20261026-0830.zip',date:mockNow-86400000,size:'12.1 MB'}],
  destination:'https://nas-host.local/webdav/backups/',
  jobs:[
    {id:'j1',action:'backup',target:'Magpie',status:'success',date:mockNow-3600000,progress:100,logs:[{time:'08:30:01',stream:'stdout',text:'[mock] nas-host received backup request: Magpie'},{time:'08:30:02',stream:'stdout',text:'Archive created. Uploading to WebDAV…'},{time:'08:30:05',stream:'stdout',text:'Checksum verified. Backup complete (12.4 MB). Exit code: 0'}]},
    {id:'j2',action:'restart',target:'AdGuard Home',status:'success',date:mockNow-7200000,progress:100,logs:[{time:'07:30:01',stream:'stdout',text:'[mock] Restarting AdGuard Home on compute-host…'},{time:'07:30:04',stream:'stdout',text:'Health check passed. Service running. Exit code: 0'}]},
    {id:'j3',action:'upgrade',target:'Immich',service:'s3',status:'failed',date:mockNow-86400000,progress:60,logs:[{time:'09:12:01',stream:'stdout',text:'[mock] Pulling image for Immich…'},{time:'09:12:08',stream:'stderr',text:'REGISTRY_TIMEOUT: Image registry did not respond within 30 seconds.'},{time:'09:12:09',stream:'stderr',text:'Upgrade aborted. Existing version remains running. Exit code: 1'}],error:'REGISTRY_TIMEOUT · 映像來源連線逾時；目前版本持續運作。'}
  ]
};
const STORAGE = 'unified-prototype-v1';
let state;
try { state = JSON.parse(localStorage.getItem(STORAGE)) || structuredClone(seed); if (!Array.isArray(state.hosts) || !Array.isArray(state.services) || !Array.isArray(state.jobs) || !Array.isArray(state.backups)) throw new Error('Invalid mock data'); }
catch { state = structuredClone(seed); }
state.jobs.filter(j => j.status === 'running').forEach(j => {j.status='failed'; j.error='MOCK_INTERRUPTED · 頁面重新載入，模擬任務已中斷。'; j.logs.push({time:stamp(),stream:'stderr',text:j.error});});
let page = 'services', serviceFilter = 'all', hostFilter = 'all', query = '', historyFilter = 'all', selectedJob = null, streamFilter = 'all';
let sshTarget = '', sshLines = [];
let toastTimer;
function save(){try{localStorage.setItem(STORAGE, JSON.stringify(state));}catch{toast('瀏覽器儲存空間不可用；本次操作仍可繼續。');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
const hostOf = service => state.hosts.find(h=>h.id===service.host);
const busy = id => state.jobs.some(j=>j.status==='running' && j.service===id);
const backupBusy = client => state.jobs.some(j=>j.status==='running' && ['backup','restore'].includes(j.action) && j.target===client);
const statusLabel = {online:'運行中',stopped:'已停止',running:'執行中',success:'成功',failed:'失敗'};
function badge(status){return `<span class="status ${status==='online'||status==='success'?'':status}"><i class="tiny-dot"></i>${statusLabel[status] || esc(status)}</span>`;}
function button(text, action, id='', style='', symbol=''){return `<button class="button ${style}" data-action="${action}" data-id="${esc(id)}">${symbol?icon(symbol):''}${text}</button>`;}
function pageHead(eyebrow,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}<span class="dot">.</span></h1><p class="description">${description}</p></div><div class="head-actions">${actions}</div></div>`;}
function renderNav(){ $('#navigation').innerHTML=navs.map(n=>`<a class="nav-item ${page===n.id?'active':''}" href="#${n.id}" ${page===n.id?'aria-current="page"':''}>${icon(n.icon)}<span>${n.label}</span>${n.id==='services'?`<span class="count">${state.services.length}</span>`:n.id==='history'&&state.jobs.some(j=>j.status==='running')?`<span class="count">${state.jobs.filter(j=>j.status==='running').length}</span>`:''}</a>`).join(''); $('#breadcrumb').textContent=navs.find(n=>n.id===page).label; }
function render(){renderNav();$('#main').innerHTML=page==='services'?servicesView():page==='hosts'?hostsView():page==='backups'?backupsView():historyView();renderDock();}
function stat(label,value,unit,note,kind,symbol){return `<div class="stat"><div class="stat-label">${label}${icon(symbol)}</div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-note ${kind}">${note}</div></div>`;}
function hostMini(h){return `<button class="host-mini" data-action="host-detail" data-id="${h.id}"><span class="host-icon">${icon('host')}</span><div class="host-info"><div class="host-name">${esc(h.name)}${h.central?'<span class="tag">CENTRAL</span>':''}</div><div class="host-meta">${esc(h.address)} · ${state.services.filter(s=>s.host===h.id).length} services</div></div><span class="host-health ${h.online?'':'off'}"><i class="tiny-dot"></i>${h.online?'在線':'離線'}</span></button>`;}
function servicesView(){const running=state.services.filter(s=>s.status==='online').length,updates=state.services.filter(s=>s.version!==s.latest).length;
return `${pageHead('YOUR INFRASTRUCTURE, AT A GLANCE','服務總覽','每一台主機，每一個服務。在這裡掌握全局。',button('新增服務','add-service','','primary','plus'))}
<div class="stats">${stat('已連線主機',state.hosts.filter(h=>h.online).length,`/ ${state.hosts.length} 台`,'中央管理 · nas-host','green','host')}${stat('運行中服務',running,`/ ${state.services.length} 個`,`${state.services.length-running} 個服務已停止`,'','grid')}${stat('可用更新',updates,'個服務',updates?'有新版本可供更新':'所有服務皆為最新版本','amber','update')}${stat('最近備份',state.backups.length?'已完成':'尚無','',state.backups.length?`${formatDate(state.backups[0].date)} · WebDAV`:'建立第一份備份','','shield')}</div>
<div class="section-top"><h2>主機概況 <span>${state.hosts.length} hosts</span></h2><a class="text-button" href="#hosts">管理主機 ${icon('arrow')}</a></div><div class="hosts-strip">${state.hosts.map(hostMini).join('')}</div>
<section class="panel"><div class="panel-heading section-top"><h2>所有服務</h2><span class="text-button">${icon('clock')} 本機模擬狀態</span></div><div class="toolbar"><div class="tabs" aria-label="服務篩選">${[['all','全部',state.services.length],['online','運行中',running],['updates','可更新',updates],['stopped','已停止',state.services.length-running]].map(([id,label,count])=>`<button class="tab ${serviceFilter===id?'active':''}" data-action="service-filter" data-id="${id}" aria-pressed="${serviceFilter===id}">${label}<span>${count}</span></button>`).join('')}</div><div class="filters"><div class="search">${icon('search')}<input id="service-search" aria-label="搜尋服務" placeholder="搜尋服務…" value="${esc(query)}"></div><select id="host-filter" aria-label="依主機篩選"><option value="all">所有主機</option>${state.hosts.map(h=>`<option value="${h.id}" ${h.id===hostFilter?'selected':''}>${esc(h.name)}</option>`).join('')}</select></div></div><div id="service-results">${serviceResults()}</div></section>
<div class="bottom-grid"><section class="panel small-panel"><div class="section-top"><h2>最近活動</h2><a href="#history" class="text-button">查看全部 ${icon('arrow')}</a></div>${state.jobs.slice(0,3).map(activityRow).join('')}</section><section class="panel small-panel"><div class="section-top"><h2>安心備份，隨時還原</h2><span class="tag">WEBDAV</span></div><p class="description">集中管理 Magpie 與 Flutter ServerBox 的備份。</p><div class="backup-summary">${icon('cloud')}<div><strong>nas-host / backups</strong><small>${state.backups.length} 份可還原備份 · Mock storage</small></div><button class="action-icon" data-action="go-backups" aria-label="開啟備份與還原">${icon('arrow')}</button></div><div class="backup-clients"><span><i class="tiny-dot"></i> Magpie</span><span><i class="tiny-dot"></i> Flutter ServerBox</span><button class="text-button" data-action="backup" style="margin-left:auto">建立備份 ${icon('arrow')}</button></div></section></div>`;}
function serviceResults(){const list=state.services.filter(s=>(hostFilter==='all'||s.host===hostFilter)&&s.name.toLowerCase().includes(query.toLowerCase())&&(serviceFilter==='all'||serviceFilter==='updates'&&s.latest!==s.version||s.status===serviceFilter));return list.length?`<table class="service-table"><thead><tr><th>服務名稱</th><th>主機</th><th>狀態</th><th class="version-col">版本</th><th style="text-align:right">操作</th></tr></thead><tbody>${list.map(serviceRow).join('')}</tbody></table><div class="table-footer"><span>顯示 ${list.length} / ${state.services.length} 個服務</span><span>所有操作由 nas-host 執行</span></div>`:'<div class="empty"><strong>沒有符合條件的服務</strong>試著調整關鍵字或篩選條件。</div>';}
function serviceRow(s){const h=hostOf(s);return `<tr><td><button class="service-name" data-action="service-detail" data-id="${s.id}"><span class="service-logo ${s.color}">${esc(s.logo)}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.kind)}</small></span></button></td><td class="host-col host-cell">${esc(h.name)}</td><td class="status-col">${badge(busy(s.id)?'running':s.status)}</td><td class="version-col"><div class="version">v${esc(s.version)}${s.latest!==s.version?`<span class="upgrade">↑ v${esc(s.latest)} 可更新</span>`:''}</div></td><td class="actions-col"><div class="row-actions">${s.latest!==s.version?`<button class="button compact" data-action="upgrade" data-id="${s.id}" ${busy(s.id)?'disabled':''}>${icon('update')}更新</button>`:''}<button class="action-icon" data-action="${s.status==='online'?'restart':'start'}" data-id="${s.id}" aria-label="${s.status==='online'?'重啟':'啟動'} ${esc(s.name)}" title="${s.status==='online'?'重新啟動':'啟動'}" ${busy(s.id)?'disabled':''}>${icon(s.status==='online'?'restart':'play')}</button><button class="action-icon" data-action="service-detail" data-id="${s.id}" aria-label="${esc(s.name)} 詳情與更多操作" title="詳情與更多操作">${icon('more')}</button></div></td></tr>`;}
function activityRow(j){return `<button class="activity-row" style="width:100%;text-align:left" data-action="job" data-id="${j.id}"><span class="activity-symbol ${j.status}">${icon(j.status==='failed'?'close':j.status==='running'?'clock':'check')}</span><div class="activity-content"><strong>${esc(j.target)} · ${actionNames[j.action]}${j.status==='success'?'完成':j.status==='failed'?'失敗':'執行中'}</strong><small>${j.status==='failed'?'查看錯誤與完整輸出':'nas-host · Job Console'}</small></div><span class="activity-time">${formatDate(j.date)}</span></button>`;}
function hostsView(){return `${pageHead('CONNECTED MACHINES','主機','跨主機管理服務，由 nas-host 統一協調操作。',button('新增主機','add-host','','primary','plus'))}<div class="notice">${icon('host')}nas-host 為中央 Application Layer。新增主機後，即可為該主機加入服務。</div><div class="host-grid">${state.hosts.map(h=>`<section class="panel host-card"><div style="display:flex;justify-content:space-between"><span class="host-icon">${icon('host')}</span>${badge(h.online?'online':'stopped')}</div><h3>${esc(h.name)} ${h.central?'<span class="tag">CENTRAL</span>':''}</h3><div class="host-meta">${esc(h.platform)} · ${esc(h.address)}</div><dl class="key-values"><div><dt>已登記服務</dt><dd>${state.services.filter(s=>s.host===h.id).length} 個</dd></div><div><dt>運行中</dt><dd>${state.services.filter(s=>s.host===h.id&&s.status==='online').length} 個</dd></div></dl>${button('主機詳情','host-detail',h.id,'','arrow')}</section>`).join('')}</div>`;}
function backupsView(){return `${pageHead('BACK UP. RESTORE. RELAX.','備份與還原','為重要設定留一份安心的副本。',button('建立備份','backup','','primary','plus'))}<div class="notice">${icon('info')}此處模擬 Magpie / Flutter ServerBox 的 WebDAV 備份與還原。執行輸出可在 Job Console 即時查看。</div><section class="panel"><div class="backup-head"><span class="host-icon">${icon('cloud')}</span><div style="min-width:0"><h3>WebDAV 備份空間</h3><p style="overflow-wrap:anywhere">${esc(state.destination)}</p></div><div class="head-actions">${button('編輯位置','destination','','compact')}</div></div><div class="toolbar"><h2>備份檔案 <span style="color:var(--muted);font-size:11px">${state.backups.length} 份</span></h2><span class="text-button">${icon('shield')} 模擬完整性驗證</span></div>${state.backups.length?`<table class="service-table backup-table"><thead><tr><th>備份來源 / 檔案</th><th>建立時間</th><th class="version-col">大小</th><th>狀態</th><th style="text-align:right">操作</th></tr></thead><tbody>${state.backups.map(b=>`<tr><td><div class="service-name"><span class="service-logo ${b.client==='Magpie'?'':'blue'}">${b.client==='Magpie'?'M':'S'}</span><span><strong>${esc(b.client)}</strong><small>${esc(b.name)}</small></span></div></td><td class="host-col">${formatDate(b.date)}</td><td class="version-col version">${b.size}</td><td class="status-col"><span class="status">${icon('check')}可還原</span></td><td class="actions-col">${button('還原','restore',b.id,'compact','history')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">尚無備份，請先建立一份備份。</div>'}</section>`;}
function historyView(){const list=state.jobs.filter(j=>historyFilter==='all'||j.status===historyFilter);return `${pageHead('EVERY ACTION, ACCOUNTED FOR','執行紀錄','追蹤每一次操作，查看執行結果與完整日誌。')}<section class="panel"><div class="toolbar"><div class="tabs">${[['all','全部'],['running','執行中'],['success','成功'],['failed','失敗']].map(([id,label])=>`<button class="tab ${historyFilter===id?'active':''}" data-action="history-filter" data-id="${id}" aria-pressed="${historyFilter===id}">${label}</button>`).join('')}</div><span class="text-button">${state.jobs.length} 個任務 · 本機保存</span></div><div class="history-list">${list.length?list.map(j=>`<div class="history-row"><span class="activity-symbol ${j.status}">${icon(j.status==='failed'?'close':j.status==='running'?'clock':'check')}</span><div class="activity-content"><strong>${esc(j.target)} · ${actionNames[j.action]}</strong><small>${formatDate(j.date)} · ${esc(j.id)}${j.error?`<br><span style="color:var(--red)">${esc(j.error)}</span>`:''}</small></div>${badge(j.status)}${button('查看輸出','job',j.id,'compact','terminal')}</div>`).join(''):'<div class="empty">這個分類尚無執行紀錄。</div>'}</div></section>`;}
function openModal(title,body,footer='',form=''){
  const m=$('#modal'); if(m.open)m.close();
  m.innerHTML=`${form?`<form id="${form}">`:''}<div class="modal-head"><h2 id="modal-title">${title}</h2><button type="button" class="icon-button" data-action="close-modal" aria-label="關閉">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}${form?'</form>':''}`;
  m.showModal();
}
const cancel = '<button type="button" class="button" data-action="close-modal">取消</button>';
const submit = text => `<button type="submit" class="button primary">${text}</button>`;
function serviceDetail(id){const s=state.services.find(s=>s.id===id),h=hostOf(s);openModal('服務詳情',`<div class="detail-top"><span class="service-logo ${s.color}">${esc(s.logo)}</span><div><h3>${esc(s.name)}</h3><div style="margin-top:7px">${badge(busy(id)?'running':s.status)}</div></div></div><dl class="key-values"><div><dt>所在主機</dt><dd>${esc(h.name)}</dd></div><div><dt>管理方式</dt><dd>${esc(s.kind)}</dd></div><div><dt>目前版本</dt><dd>v${esc(s.version)}</dd></div><div><dt>最新版本</dt><dd>v${esc(s.latest)}</dd></div></dl><div class="detail-actions">${busy(id)?'<p class="description">此服務有任務執行中，可從執行紀錄查看輸出。</p>':`${s.status==='online'?button('停止','stop',id,'danger','stop')+button('重新啟動','restart',id,'','restart'):button('啟動','start',id,'primary','play')}${s.version!==s.latest?button('更新版本','upgrade',id,'','update'):''}`}</div><div class="detail-section"><h2>操作日誌</h2><p>每次管理操作會建立獨立 Job，可持續查看背景任務輸出。</p>${button('查看此服務最近任務','service-job',id,'','terminal')}</div><div class="detail-section" style="margin-top:22px"><h2>手動排錯</h2><p>Interactive SSH Terminal 提供互動指令介面，由 nas-host Terminal Gateway 連至 ${esc(h.name)}。目前為指令模擬。</p>${button('開啟 SSH Terminal','ssh-service',id,'','terminal')}</div>`);}
function hostDetail(id){const h=state.hosts.find(h=>h.id===id),list=state.services.filter(s=>s.host===id);openModal('主機詳情',`<div class="detail-top"><span class="host-icon">${icon('host')}</span><div><h3>${esc(h.name)}</h3><div class="description">${esc(h.platform)}</div></div></div><dl class="key-values"><div><dt>主機位址</dt><dd>${esc(h.address)}</dd></div><div><dt>角色</dt><dd>${h.central?'中央 Application Layer':'受管理主機'}</dd></div></dl><div class="section-top"><h2>服務 · ${list.length}</h2>${button('新增服務','add-service',id,'compact','plus')}</div>${list.map(s=>`<div class="activity-row"><button class="service-name" data-action="service-detail" data-id="${s.id}"><span class="service-logo ${s.color}">${esc(s.logo)}</span><strong>${esc(s.name)}</strong></button><span style="margin-left:auto">${badge(s.status)}</span></div>`).join('')||'<p class="description">加入第一個服務，開始集中管理。</p>'}<div class="detail-section" style="margin-top:20px"><h2>手動排錯</h2><p>透過 nas-host Terminal Gateway 開啟互動 SSH 工作階段。此 Prototype 僅模擬輸入與回應。</p>${button('開啟 SSH Terminal','ssh-host',id,'','terminal')}</div>`);}
function addHost(){openModal('新增主機','<p>將新主機加入工作區，再登記需要管理的服務。</p><label class="field">主機名稱<input name="name" required maxlength="40" placeholder="例如：tw-lab" autofocus></label><label class="field">IP 位址或主機名稱<input name="address" required maxlength="100" placeholder="例如：192.0.2.40"><small>僅儲存 Mock Data，不會建立實際連線。</small></label><label class="field">作業系統<select name="platform"><option>Ubuntu 24.04</option><option>Debian 12</option><option>OpenMediaVault</option><option>其他 Linux</option></select></label>',cancel+submit('新增主機'),'host-form');}
function addService(host=''){openModal('新增服務',`<p>服務由中央 Application Layer 管理，兩個客戶端具有相同操作能力。</p><label class="field">服務名稱<input name="name" required maxlength="50" placeholder="例如：Paperless" autofocus></label><label class="field">所在主機<select name="host">${state.hosts.map(h=>`<option value="${h.id}" ${host===h.id?'selected':''}>${esc(h.name)}</option>`).join('')}</select></label><div class="field-pair"><label class="field">目前版本<input name="version" required maxlength="20" value="1.0.0"></label><label class="field">可用版本<input name="latest" required maxlength="20" value="1.1.0"></label></div><label class="field">初始狀態<select name="status"><option value="online">運行中</option><option value="stopped">已停止</option></select></label>`,cancel+submit('新增服務'),'service-form');}
function simulationOptions(){return '<label class="field">模擬執行情境<select name="scenario"><option value="normal">正常完成 · 約 12 秒</option><option value="long">長時間背景任務 · 約 45 秒</option><option value="fail">執行失敗 · 查看 stderr 與錯誤</option></select><small>可關閉 Console 並繼續操作；保持頁面開啟，背景模擬會繼續執行。</small></label>';}
function requestOperation(action,id){const s=state.services.find(s=>s.id===id);if(!s||busy(id))return toast('此服務已有執行中的任務。');openModal(`${actionNames[action]} ${esc(s.name)}`,`<input type="hidden" name="action" value="${action}"><input type="hidden" name="service" value="${id}"><p>執行主機：${esc(hostOf(s).name)}<br>協調執行：nas-host Application Layer</p>${action==='upgrade'?`<div class="notice">版本 v${esc(s.version)} → v${esc(s.latest)}</div>`:''}${action==='stop'?'<div class="danger-note">停止後，此服務將暫時無法使用。可隨時從詳情重新啟動。</div>':''}${simulationOptions()}`,cancel+submit(`開始${actionNames[action]}`),'operation-form');}
function backupForm(){openModal('建立 WebDAV 備份',`<p>選擇應用程式，將設定封裝至目前的 WebDAV 備份位置。</p><label class="field">備份來源<select name="client"><option>Magpie</option><option>Flutter ServerBox</option></select></label><div class="notice" style="overflow-wrap:anywhere">${esc(state.destination)}</div>${simulationOptions()}`,cancel+submit('開始備份'),'backup-form');}
function restoreForm(id){const b=state.backups.find(b=>b.id===id);if(backupBusy(b.client))return toast('此應用程式已有備份或還原任務執行中。');openModal(`還原 ${esc(b.client)}`,`<input type="hidden" name="backup" value="${id}"><p>備份檔案：${esc(b.name)}<br>建立時間：${formatDate(b.date)}<br>還原目標：${esc(b.client)} · nas-host</p><div class="danger-note">還原會覆蓋目前的應用程式設定。本次操作只會變更模擬資料。</div><label class="radio-option"><input type="checkbox" name="confirm" required> 我確認將此備份還原至 ${esc(b.client)}</label><div style="height:12px"></div>${simulationOptions()}`,cancel+submit('開始還原'),'restore-form');}
function startJob(action, target, scenario, service=null, backup=null){
  if(service&&busy(service)||['backup','restore'].includes(action)&&backupBusy(target))return toast('相同目標已有執行中的任務。');
  const j={id:uid('job'),action,target,service,backup,scenario,status:'running',date:Date.now(),progress:0,logs:[],destination:state.destination};
  state.jobs.unshift(j); $('#modal').close(); save(); render(); openConsole(j.id);
  const steps={
    upgrade:['Connecting to target host…','Checking current version and service health…','Pulling new image… 24%','Pulling new image… 68%','Image download complete. Verifying digest…','Recreating service with new version…','Waiting for health check…','Health check passed. Upgrade complete.'],
    start:['Connecting to target host…','Loading service configuration…','Checking dependencies…','Preparing service…','Starting containers…','Waiting for readiness…','Checking service health…','Service is running.'],
    stop:['Connecting to target host…','Loading service configuration…','Requesting graceful shutdown…','Waiting for active requests…','Stopping service…','Releasing service resources…','Verifying stopped state…','Service stopped.'],
    restart:['Connecting to target host…','Loading service configuration…','Requesting graceful shutdown…','Stopping containers…','Starting containers…','Waiting for readiness…','Checking service health…','Service restarted and healthy.'],
    backup:['Reading application configuration…','Collecting backup files…','Creating ZIP archive…','Calculating archive checksum…','Connecting to WebDAV destination…','Uploading backup… 52%','Verifying uploaded archive…','Backup stored and verified.'],
    restore:['Reading selected WebDAV archive…','Verifying checksum…','Downloading archive…','Validating application compatibility…','Preparing application settings…','Restoring selected backup…','Validating restored configuration…','Restore completed successfully.']
  }[action];
  appendLog(j,'stdout',`[mock] nas-host accepted ${action} request: ${target}.`);
  if(['backup','restore'].includes(action))appendLog(j,'stdout',`WebDAV: ${j.destination}`);
  if(backup){const b=state.backups.find(b=>b.id===backup);appendLog(j,'stdout',`Selected archive: ${b.name}`);}
  let i=0;
  const timer=setInterval(()=>{
    if(scenario==='fail'&&i===4){j.status='failed';j.error=action==='backup'||action==='restore'?'WEBDAV_TIMEOUT · WebDAV 連線逾時，請檢查備份位置後重試。':'HOST_TIMEOUT · 主機回應逾時，請檢查連線後重試。';appendLog(j,'stderr',j.error);appendLog(j,'stderr','Operation aborted before applying changes. Exit code: 1');clearInterval(timer);finishJob(j);return;}
    appendLog(j,'stdout',steps[i]);i++;j.progress=Math.round(i/steps.length*100);
    if(i===steps.length){j.status='success';appendLog(j,'stdout','Job completed. Exit code: 0');clearInterval(timer);applyJobResult(j);finishJob(j);}else{save();renderConsoleBody();renderDock();}
  },scenario==='long'?5600:1500);
}
function appendLog(j,stream,text){j.logs.push({time:stamp(),stream,text});renderConsoleBody();}
function applyJobResult(j){const s=state.services.find(s=>s.id===j.service);if(s){if(j.action==='upgrade')s.version=s.latest;if(j.action==='stop')s.status='stopped';if(['start','restart','upgrade'].includes(j.action))s.status='online';}if(j.action==='backup'){state.backups.unshift({id:uid('backup'),client:j.target,name:`${j.target==='Magpie'?'magpie':'serverbox'}-${new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14)}.zip`,date:Date.now(),size:j.target==='Magpie'?'12.4 MB':'2.8 MB'});}if(j.action==='restore'){state.lastRestore={client:j.target,backup:j.backup,date:Date.now()};const b=state.backups.find(b=>b.id===j.backup);appendLog(j,'stdout',`Applied configuration snapshot: ${b.name}`);}}
function finishJob(j){j.finished=Date.now();save();render();renderConsoleBody();toast(`${j.target} · ${actionNames[j.action]}${j.status==='success'?'完成':'失敗，請查看日誌'}`);}
function renderDock(){const jobs=state.jobs.filter(j=>j.status==='running');$('#job-dock').innerHTML=jobs.length?`<button class="job-dock" data-action="job" data-id="${jobs[0].id}"><span class="spinner"></span><span>${jobs.length} 個背景任務執行中<small>${esc(jobs[0].target)} · ${actionNames[jobs[0].action]} · ${jobs[0].progress}%</small></span>${icon('arrow')}</button>`:'';}
function openConsole(id){selectedJob=id;streamFilter='all';const c=$('#console');if($('#modal').open)$('#modal').close();if(c.open)c.close();c.innerHTML=`<div class="modal-head"><div><h2 id="console-title">Job Console</h2><div class="console-title-meta" id="console-meta"></div></div><button class="icon-button" data-action="close-console" aria-label="關閉 Console">${icon('close')}</button></div><div id="console-status" class="console-status"></div><div class="progress"><span id="console-progress"></span></div><div class="console-tools"><span class="tag">EXECUTION OUTPUT</span><label for="stream-filter">輸出串流</label><select id="stream-filter"><option value="all">全部輸出</option><option value="stdout">stdout</option><option value="stderr">stderr</option></select></div><div class="terminal" id="job-output" role="log" aria-live="polite" aria-label="任務執行輸出"></div><div id="job-error"></div><div class="console-hint">此為操作輸出的唯讀 Console。關閉後任務仍會繼續；可從執行紀錄重新開啟完整日誌。</div><div class="console-foot"><p>MOCK EXECUTION · nas-host</p><div class="head-actions">${button('下載完整日誌','download-log','','compact')}${button('關閉','close-console','','primary compact')}</div></div>`;c.showModal();renderConsoleBody();}
function renderConsoleBody(){if(!selectedJob||!$('#job-output')||!$('#console').open)return;const j=state.jobs.find(j=>j.id===selectedJob);$('#console-meta').textContent=`${j.target} / ${actionNames[j.action]} · ${j.id}`;$('#console-status').innerHTML=`${badge(j.status)}<span>${j.status==='running'?`背景執行中 · ${j.progress}%`:j.status==='success'?'操作已完成 · Exit code 0':'執行失敗 · Exit code 1'}</span><span style="margin-left:auto;color:var(--muted)">${formatDate(j.date)}</span>`;$('#console-progress').style.width=j.progress+'%';const out=$('#job-output'),atBottom=out.scrollHeight-out.scrollTop-out.clientHeight<45;const logs=j.logs.filter(l=>streamFilter==='all'||l.stream===streamFilter);out.innerHTML=logs.length?logs.map(l=>`<div class="log-line"><span class="log-time">${esc(l.time)}</span><span class="log-stream ${l.stream}">${l.stream}</span><span class="log-text ${l.stream==='stderr'?'log-error':''}">${esc(l.text)}</span></div>`).join(''):'<span style="color:#839a89">此串流尚無輸出。</span>';if(atBottom)out.scrollTop=out.scrollHeight;$('#job-error').innerHTML=j.error?`<div class="danger-note" style="margin:0;border-radius:0">${esc(j.error)}<br>可回到原操作重新執行，並選擇「正常完成」模擬復原。</div>`:'';}
function downloadLog(){const j=state.jobs.find(j=>j.id===selectedJob);const blob=new Blob([`Unified Job Console — MOCK EXECUTION\n${j.target} / ${j.action} / ${j.status}\n${j.logs.map(l=>`[${l.time}] [${l.stream}] ${l.text}`).join('\n')}\n`],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${j.id}.log`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('完整日誌已下載。');}
function ssh(host,service=null){selectedJob=null;sshTarget=host.name;sshLines=[`Interactive SSH Terminal · MOCK SESSION`,`Gateway: nas-host → ${host.name} (${host.address})`,...(service?[`Service context: ${service.name}`]:[]),'此終端僅提供預設模擬回應，輸入 help 查看可用指令。',''];if($('#modal').open)$('#modal').close();const c=$('#console');if(c.open)c.close();c.innerHTML=`<div class="modal-head"><div><h2 id="console-title">Interactive SSH Terminal</h2><div class="console-title-meta">手動排錯 · ${esc(host.name)} · Terminal Gateway</div></div><button class="icon-button" data-action="close-console" aria-label="關閉 SSH Terminal">${icon('close')}</button></div><div class="console-status"><span class="status"><i class="tiny-dot"></i>模擬工作階段</span><span>互動指令</span></div><div class="terminal" id="ssh-output" role="log" aria-live="polite"></div><form id="ssh-form" class="terminal-input"><span>admin@${esc(host.name)}:~$</span><input name="command" aria-label="SSH 模擬指令" placeholder="輸入 help" autocomplete="off" spellcheck="false"><button type="submit">送出 ↵</button></form><div class="console-hint">未來由 nas-host Terminal Gateway 提供連線。Web 與 Android 均可使用此功能。此工作階段不會建立管理 Job。</div>`;c.showModal();renderSSH();$('#ssh-form input').focus();}
function renderSSH(){const out=$('#ssh-output');out.textContent=sshLines.join('\n');out.scrollTop=out.scrollHeight;}
function runSSH(command){const cmd=command.trim();if(!cmd)return;if(cmd==='clear'){sshLines=[];renderSSH();return;}if(cmd==='exit'){ $('#console').close();return;}sshLines.push(`admin@${sshTarget}:~$ ${cmd}`);const h=state.hosts.find(h=>h.name===sshTarget);const results={help:'可用模擬指令：help, pwd, ls, whoami, hostname, uptime, docker ps, clear, exit',pwd:'/home/admin',ls:'compose/  backups/  logs/',whoami:'admin',hostname:sshTarget,uptime:'up 14 days, load average: 0.12, 0.08, 0.05','docker ps':`NAME                    STATUS\n${state.services.filter(s=>s.host===h.id&&s.status==='online').map(s=>`${s.name.padEnd(24)}Up (mock)`).join('\n')||'(no running containers)'}`};sshLines.push(results[cmd]||'此 Prototype 未模擬這個指令。輸入 help 查看可用指令。','');renderSSH();}
function architecture(){openModal('共同能力，兩種客戶端',`<p>Web UI 與 Android App 是完整、平等的客戶端，透過同一個 Application Layer 取得狀態、發起操作與顯示結果。</p><div class="architecture-grid"><div class="architecture-box">Web UI<small>獨立技術框架與桌面佈局</small></div><div class="architecture-box">Android App<small>獨立技術框架與行動佈局</small></div></div><div class="architecture-arrow">↓　相同 Application Services　↓</div><div class="architecture-central"><strong>nas-host NAS · Docker Compose</strong><p>中央 Application Layer<br>業務邏輯 · 服務管理 · 背景任務 · 備份還原<br>Job Output / History · Terminal Gateway / SSH</p></div><table class="parity-table"><thead><tr><th>功能與操作能力</th><th>Web</th><th>Android</th></tr></thead><tbody>${['多主機服務狀態','更新 / 啟動 / 停止 / 重啟','即時 Job Console 與完整日誌','WebDAV 備份 / 還原','動態新增主機 / 服務','Interactive SSH Terminal'].map(t=>`<tr><td>${t}</td><td>✓</td><td>✓</td></tr>`).join('')}</tbody></table><p style="margin:18px 0 0">參考 SessionsFold 共用 Application Services 的設計理念。客戶端各自選擇前端框架與元件，功能維持 1:1。本階段提供 HTML 桌面與行動版互動稿，所有操作由 Mock Data 模擬。</p>`);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;
  if(a==='close-modal')$('#modal').close();else if(a==='close-console')$('#console').close();else if(a==='add-host')addHost();else if(a==='add-service')addService(id);else if(a==='host-detail')hostDetail(id);else if(a==='service-detail')serviceDetail(id);else if(a==='architecture')architecture();else if(a==='service-filter'){serviceFilter=id;render();}else if(a==='history-filter'){historyFilter=id;render();}else if(['upgrade','start','stop','restart'].includes(a))requestOperation(a,id);else if(a==='backup')backupForm();else if(a==='restore')restoreForm(id);else if(a==='job')openConsole(id);else if(a==='download-log')downloadLog();else if(a==='go-backups')location.hash='backups';else if(a==='ssh-host')ssh(state.hosts.find(h=>h.id===id));else if(a==='ssh-service'){const s=state.services.find(s=>s.id===id);ssh(hostOf(s),s);}else if(a==='service-job'){const s=state.services.find(s=>s.id===id),j=state.jobs.find(j=>j.service===id||j.target===s.name);if(j)openConsole(j.id);else toast('此服務尚無執行紀錄，執行操作後即可查看。');}else if(a==='destination')openModal('WebDAV 備份位置',`<p>設定模擬備份目的地。正式連線與憑證將由 nas-host 管理。</p><label class="field">WebDAV URL<input name="destination" type="url" required value="${esc(state.destination)}"><small>請使用 http:// 或 https:// 開頭的位址。</small></label>`,cancel+submit('儲存位置'),'destination-form');
});
document.addEventListener('input',e=>{if(e.target.id==='service-search'){query=e.target.value;$('#service-results').innerHTML=serviceResults();}});
document.addEventListener('change',e=>{if(e.target.id==='host-filter'){hostFilter=e.target.value;$('#service-results').innerHTML=serviceResults();}if(e.target.id==='stream-filter'){streamFilter=e.target.value;renderConsoleBody();}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form));
  if(form.id==='host-form'){d.name=d.name.trim();d.address=d.address.trim();if(!d.name||!d.address)return toast('請填入主機名稱與位址。');if(state.hosts.some(h=>h.name.toLowerCase()===d.name.toLowerCase()||h.address.toLowerCase()===d.address.toLowerCase()))return toast('主機名稱或位址已存在。');state.hosts.push({id:uid('h'),...d,online:true});save();$('#modal').close();render();toast(`${d.name} 已加入工作區。`);}
  else if(form.id==='service-form'){d.name=d.name.trim();d.version=d.version.trim();d.latest=d.latest.trim();if(!d.name||!d.version||!d.latest)return toast('請填入服務名稱與版本。');if(state.services.some(s=>s.host===d.host&&s.name.toLowerCase()===d.name.toLowerCase()))return toast('此主機已登記相同名稱的服務。');state.services.push({id:uid('s'),...d,kind:'Docker Compose',logo:d.name.charAt(0).toUpperCase(),color:'blue'});save();$('#modal').close();render();toast(`${d.name} 已加入服務清單。`);}
  else if(form.id==='operation-form'){const s=state.services.find(s=>s.id===d.service);startJob(d.action,s.name,d.scenario,s.id);}
  else if(form.id==='backup-form')startJob('backup',d.client,d.scenario);
  else if(form.id==='restore-form'){const b=state.backups.find(b=>b.id===d.backup);startJob('restore',b.client,d.scenario,null,b.id);}
  else if(form.id==='destination-form'){const url=new URL(d.destination);if(!['http:','https:'].includes(url.protocol))return toast('請使用 HTTP 或 HTTPS WebDAV 位址。');state.destination=d.destination;save();$('#modal').close();render();toast('WebDAV 模擬位置已儲存。');}
  else if(form.id==='ssh-form'){runSSH(d.command);form.reset();}
});
function navigate(){page=navs.some(n=>n.id===location.hash.slice(1))?location.hash.slice(1):'services';render();window.scrollTo(0,0);}
window.addEventListener('hashchange',navigate);
navigate();
save();
